/**
 * The WF-002 step-kind catalog — the machine-readable description of every
 * workflow step kind, plus the write-time validation derived from it.
 *
 * WHY THIS FILE EXISTS AND WHY IT IS SHAPED LIKE A CATALOG
 * --------------------------------------------------------
 * SUB-004's node catalog (`packages/noodl-types/src/node-catalog.json`) is
 * generated by *running the two runtime node registers* — browser
 * (`noodl-viewer-react`) and cloud (`noodl-viewer-cloud`) — and serialising
 * what registered. A workflow step kind is not registered in either: it is not
 * a graph node with ports, it is a `kind` field in a `*.workflow-def.json`
 * step DAG, executed by the WF-001 engine. It therefore cannot enter that
 * artifact, and `catalog:check` (which regenerates from the registers and
 * fails on drift) would not accept a hand-written entry — the same reason
 * library **module** nodes are documented as out of catalog scope.
 *
 * What the catalog requirement actually buys is *discoverability by the
 * semantic validator and the AI authoring loop*. That is delivered here in the
 * form that fits the artifact: a versioned, machine-readable spec table with
 * params, routes, output shape and prose, which is
 *   - served at `GET /admin/workflow-step-kinds` (so a running backend
 *     describes its own step vocabulary),
 *   - surfaced to agents through the MCP `list_backend_step_kinds` tool and the
 *     `create_backend_workflow` schema,
 *   - the single source of truth for write-time validation, so an unknown kind
 *     or a missing required param is REJECTED at `POST /admin/workflow-defs`
 *     and refuses to load from disk, and
 *   - coverage-gated by `tests/workflow-steps-catalog.test.ts`, which fails if
 *     a kind is implemented without a spec entry, or specced without author
 *     documentation in `docs/runtime/WORKFLOW-NODES.md`.
 *
 * That last point is the local equivalent of `catalog:merge:check
 * --require-coverage`: a step kind cannot ship undocumented and invisible.
 * The full argument, and why this is NOT the WF-005 "no catalog at all"
 * exemption, is in WF-002-NOTES.md.
 *
 * This module holds NO runtime dependencies (no engine, no runner) so that
 * `validateWorkflowDefinition` can consult it from the registry's load path.
 *
 * @module nodegx-backend/workflow/steps/kinds
 */

import type { StepKind, WorkflowStep } from '../types';
import { validateCondition } from './conditions';
import type { ValueLanguageSpec } from './values';
import { isPlainObject, VALUE_LANGUAGE } from './values';

/**
 * Bumped when the spec table's SHAPE changes (not when a kind is added).
 *
 * 1.1.0 — WFA-003 added `valueLanguage` (so a client can render the right
 * control for a param and know what a `$path` may address) and `raw` on a param.
 */
export const STEP_KIND_CATALOG_VERSION = '1.1.0';

export interface StepParamSpec {
  name: string;
  type: 'string' | 'number' | 'boolean' | 'enum' | 'array' | 'object' | 'condition' | 'path' | 'any';
  required?: boolean;
  default?: unknown;
  enums?: string[];
  description: string;
  /**
   * WFA-003: this param is a DSL STRUCTURE — a condition, a filter, a switch's
   * cases — not a value. Its operands use the value language, but the executor
   * evaluates them when the step runs, so the engine does not resolve the param
   * itself. Every other param IS value-resolved before the step runs.
   *
   * A property editor should render a `raw` param with its own editor (three
   * dropdowns for a condition) rather than a value/binding control.
   */
  raw?: boolean;
}

export interface StepRouteSpec {
  name: string;
  description: string;
  /** True when the route names are derived from params (switch cases). */
  dynamic?: boolean;
}

export interface StepKindSpec {
  kind: StepKind;
  displayName: string;
  category: string;
  /** The phase-11 spec this implements, for traceability. */
  source: string;
  summary: string;
  whenToUse: string;
  /** True when the step invokes a cloud function (and so needs `ref`). */
  invokesFunction: boolean;
  params: StepParamSpec[];
  routes: StepRouteSpec[];
  /** Prose description of the step's output object (what `previous` becomes). */
  output: string;
  /** The client-runtime node this mirrors, and how it differs. */
  clientEquivalent?: string;
  notes?: string[];
}

// ---------------------------------------------------------------------------
// The catalog
// ---------------------------------------------------------------------------

