/** Every implemented kind, in catalog order. */
export const STEP_KINDS = Object.keys(STEP_KIND_SPECS) as StepKind[];

export function isStepKind(v: unknown): v is StepKind {
  return typeof v === 'string' && Object.prototype.hasOwnProperty.call(STEP_KIND_SPECS, v);
}

/**
 * The params of a kind that are DSL structures rather than values, and so are
 * NOT resolved by the engine before the step runs (WFA-003). The engine asks
 * this; nothing else needs to know which they are.
 */
export function rawParamNames(kind: StepKind): ReadonlySet<string> {
  const spec = STEP_KIND_SPECS[kind];
  if (!spec) return EMPTY_RAW_PARAMS;
  const cached = RAW_PARAM_CACHE.get(kind);
  if (cached) return cached;
  const names = new Set(spec.params.filter((p) => p.raw).map((p) => p.name));
  RAW_PARAM_CACHE.set(kind, names);
  return names;
}

const EMPTY_RAW_PARAMS: ReadonlySet<string> = new Set();
const RAW_PARAM_CACHE = new Map<StepKind, ReadonlySet<string>>();

/** The wire form served by `GET /admin/workflow-step-kinds` and MCP. */
export interface StepKindCatalog {
  version: string;
  source: string;
  docs: string;
  kinds: StepKindSpec[];
  /**
   * WFA-003: how a param value may reference the run's data. Served alongside
   * the kinds because a client rendering a param editor needs both, and a
   * bundled copy of either could disagree with the backend that will execute it.
   */
  valueLanguage: ValueLanguageSpec;
}

export function stepKindCatalog(): StepKindCatalog {
  return {
    version: STEP_KIND_CATALOG_VERSION,
    source: 'nodegx-backend/workflow/steps/kinds.ts (WF-002, WFA-003)',
    docs: 'docs/runtime/WORKFLOW-NODES.md',
    kinds: STEP_KINDS.map((k) => STEP_KIND_SPECS[k]),
    valueLanguage: VALUE_LANGUAGE
  };
}

// ---------------------------------------------------------------------------
// Write-time validation
// ---------------------------------------------------------------------------

/** Hard ceiling on any single wait, in ms (24h). See the `wait` spec notes. */
export const MAX_WAIT_MS = 24 * 60 * 60 * 1000;

export const WAIT_UNIT_MS: Record<string, number> = {
  milliseconds: 1,
  seconds: 1000,
  minutes: 60 * 1000,
  hours: 60 * 60 * 1000
};

function params(step: WorkflowStep): Record<string, unknown> {
  return (step.params || {}) as Record<string, unknown>;
}

/** True for `{"$path": …}` / `{"$literal": …}` — a value that is not known yet. */
function isValueSpec(v: unknown): boolean {
  return isPlainObject(v) && (typeof v.$path === 'string' || '$literal' in v);
}

function requirePositiveNumber(v: unknown, where: string, errors: string[], min = 1): void {
  if (v === undefined) return;
  if (typeof v !== 'number' || !Number.isFinite(v) || v < min) {
    errors.push(`${where} must be a number >= ${min}`);
  }
}

/**
 * Per-kind shape validation, consulted by `validateWorkflowDefinition`. Returns
 * error strings prefixed with the step id; empty means valid.
 *
 * Everything checkable without running is checked HERE, at write time, so a
 * definition that could not possibly work is rejected with a 400 and never
 * persisted — the same doctrine as the graph-level acyclicity check.
 */
export function validateStepShape(step: WorkflowStep): string[] {
  const errors: string[] = [];
  const at = `step "${step.id}"`;
  const spec = STEP_KIND_SPECS[step.kind];
  if (!spec) {
    errors.push(`${at}: unknown kind "${String(step.kind)}" (known: ${STEP_KINDS.join(', ')})`);
    return errors;
  }

  if (spec.invokesFunction && (typeof step.ref !== 'string' || !step.ref)) {
    errors.push(`${at}: kind "${step.kind}" needs a ref (the cloud function name)`);
  }
  if (!spec.invokesFunction && step.ref) {
    errors.push(`${at}: kind "${step.kind}" does not invoke a function — remove "ref"`);
  }

  const p = params(step);
  const routeNames = Object.keys(step.routes || {});

  switch (step.kind) {
    case 'branch': {
      if (p.condition === undefined) errors.push(`${at}: branch needs a "condition" param`);
      else errors.push(...validateCondition(p.condition, `${at}.params.condition`));
      if (routeNames.length === 0) {
        errors.push(`${at}: branch needs at least one of the routes "ontrue" / "onfalse"`);
      }
      for (const r of routeNames) {
        if (r !== 'ontrue' && r !== 'onfalse') errors.push(`${at}: branch route "${r}" must be "ontrue" or "onfalse"`);
      }
      break;
    }

    case 'switch': {
      const cases = p.cases;
      if (!Array.isArray(cases) || cases.length === 0) {
        errors.push(`${at}: switch needs a non-empty "cases" array`);
        break;
      }
      const labels = new Set<string>();
      cases.forEach((c, i) => {
        const where = `${at}.params.cases[${i}]`;
        if (typeof c !== 'object' || c === null) {
          errors.push(`${where}: must be an object`);
          return;
        }
        const label = (c as { label?: unknown }).label;
        if (typeof label !== 'string' || !label) errors.push(`${where}: needs a non-empty string label`);
        else if (label === 'default') errors.push(`${where}: "default" is reserved — it is the no-match route`);
        else if (labels.has(label)) errors.push(`${where}: duplicate case label "${label}"`);
        else labels.add(label);

        const hasEquals = 'equals' in (c as object);
        const hasWhen = 'when' in (c as object);
        if (hasEquals === hasWhen) errors.push(`${where}: needs exactly one of "equals" or "when"`);
        if (hasWhen) errors.push(...validateCondition((c as { when: unknown }).when, `${where}.when`));
      });
      for (const r of routeNames) {
        if (r !== 'default' && !labels.has(r)) {
          errors.push(`${at}: route "${r}" matches no case label (labels: ${[...labels].join(', ') || 'none'})`);
        }
      }
      break;
    }

    case 'for-each': {
      requirePositiveNumber(p.maxIterations, `${at}.params.maxIterations`, errors);
      requirePositiveNumber(p.concurrency, `${at}.params.concurrency`, errors);
      if (p.filter !== undefined) errors.push(...validateCondition(p.filter, `${at}.params.filter`));
      if (p.itemKey !== undefined && typeof p.itemKey !== 'string') errors.push(`${at}.params.itemKey must be a string`);
      if (p.indexKey !== undefined && typeof p.indexKey !== 'string') {
        errors.push(`${at}.params.indexKey must be a string`);
      }
      for (const r of routeNames) {
        if (r !== 'empty' && r !== 'nonempty') errors.push(`${at}: for-each route "${r}" must be "empty" or "nonempty"`);
      }
      break;
    }

    case 'merge': {
      if (p.mode !== undefined && p.mode !== 'all' && p.mode !== 'any') {
        errors.push(`${at}.params.mode must be "all" or "any"`);
      }
      if (p.strategy !== undefined && !['object', 'array', 'shallow'].includes(String(p.strategy))) {
        errors.push(`${at}.params.strategy must be "object", "array" or "shallow"`);
      }
      if (p.sources !== undefined && (!Array.isArray(p.sources) || p.sources.some((s) => typeof s !== 'string'))) {
        errors.push(`${at}.params.sources must be an array of step ids`);
      }
      break;
    }

    case 'retry': {
      requirePositiveNumber(p.maxAttempts, `${at}.params.maxAttempts`, errors);
      requirePositiveNumber(p.delayMs, `${at}.params.delayMs`, errors, 0);
      requirePositiveNumber(p.maxDelayMs, `${at}.params.maxDelayMs`, errors, 0);
      if (p.backoffMultiplier !== undefined && (typeof p.backoffMultiplier !== 'number' || p.backoffMultiplier < 1)) {
        errors.push(`${at}.params.backoffMultiplier must be a number >= 1`);
      }
      if (p.retryOnStatus !== undefined) {
        if (!Array.isArray(p.retryOnStatus) || p.retryOnStatus.some((s) => typeof s !== 'number')) {
          errors.push(`${at}.params.retryOnStatus must be an array of HTTP status numbers`);
        }
      }
      break;
    }

    case 'stop': {
      if (p.message !== undefined && typeof p.message !== 'string') errors.push(`${at}.params.message must be a string`);
      if (p.isError !== undefined && typeof p.isError !== 'boolean') {
        errors.push(`${at}.params.isError must be a boolean`);
      }
      if ((step.next || []).length > 0 && p.isError !== false) {
        errors.push(`${at}: a stop step with isError true can never take "next" — remove the edge or set isError false`);
      }
      break;
    }

    case 'wait': {
      const unit = p.unit === undefined ? 'milliseconds' : String(p.unit);
      if (!WAIT_UNIT_MS[unit]) {
        errors.push(`${at}.params.unit must be one of ${Object.keys(WAIT_UNIT_MS).join(', ')}`);
      }
      // A duration written as a reference cannot be range-checked here — the
      // value does not exist yet. The executor already resolves it and already
      // fails loudly on a non-number and on the 24h cap, so this defers to it
      // rather than rejecting a legal definition. (`WaitStepExecutor` has
      // resolved `duration` since WF-002; write-time validation refused it,
      // which made the feature unreachable.)
      if (isValueSpec(p.duration)) break;
      if (typeof p.duration !== 'number' || !Number.isFinite(p.duration) || p.duration <= 0) {
        errors.push(`${at}.params.duration must be a number > 0`);
      } else if (WAIT_UNIT_MS[unit] && p.duration * WAIT_UNIT_MS[unit] > MAX_WAIT_MS) {
        errors.push(
          `${at}: wait of ${p.duration} ${unit} exceeds the ${MAX_WAIT_MS}ms (24h) cap — use a schedule trigger`
        );
      }
      break;
    }

    case 'wait-until': {
      if (p.target === undefined) errors.push(`${at}: wait-until needs a "target" param`);
      for (const r of routeNames) {
        if (r !== 'done' && r !== 'skipped') errors.push(`${at}: wait-until route "${r}" must be "done" or "skipped"`);
      }
      break;
    }

    case 'call-function':
    default:
      break;
  }

  // A kind with no routes in its spec must not carry a `routes` object: it
  // would be silently dead wiring (the executor never selects anything), which
  // is exactly the class of mistake SUB-005's enrichment pass exists to catch.
  if (spec.routes.length === 0 && routeNames.length > 0) {
    errors.push(`${at}: kind "${step.kind}" has no routes — use "next" / "onError" edges instead of "routes"`);
  }

  return errors;
}
